const s = $('Settings Loader').first().json;
const DEFAULT_TIMEZONE = s.timezone;
const nowET = () => DateTime.now().setZone(DEFAULT_TIMEZONE).toISO();

const input = $('Input').first().json;

const existing = $('Get Leads').all().map(i => i.json);
const norm = s => {
  const raw = String(s || '').replace(/\D/g, '');
  return (raw.length === 11 && raw.startsWith('1')) ? raw.slice(1) : raw;
};
const pad = n => 'LEAD-' + String(n).padStart(4, '0');
let row = null;
if (input.leadId) {
  row = existing.find(r => String(r['Lead ID'] || '').trim() === String(input.leadId).trim());
}
if (!row && input.phone) {
  row = existing.find(r => norm(r['Phone']) && norm(r['Phone']) === norm(input.phone));
}
let leadId, isNew, dateCreated;
if (row) {
  leadId = row['Lead ID'];
  isNew = false;
  dateCreated = row['Date Created'] || nowET();
} else {
  isNew = true;
  const nums = existing.map(r => parseInt(String(r['Lead ID'] || '').replace(/\D/g, ''), 10)).filter(n => !isNaN(n));
  leadId = pad((nums.length ? Math.max(...nums) : 0) + 1);
  dateCreated = nowET();
}
const prev = row || {};
const pick = (a, b) => (a !== undefined && a !== null && String(a).trim() !== '') ? a : (b || '');
const now = nowET();

const followUpCount = (input.followUpCount !== undefined && input.followUpCount !== null && String(input.followUpCount).trim() !== '')
  ? String(input.followUpCount)
  : pick(prev['Follow-up Count'], '0');

const leadRow = {
  'Lead ID': leadId,
  'Date Created': dateCreated,
  'Source': pick(input.source, prev['Source']),
  'First Name': pick(input.firstName, prev['First Name']),
  'Last Name': pick(input.lastName, prev['Last Name']),
  'Phone': pick(input.phone, prev['Phone']),
  'Email': pick(input.email, prev['Email']),
  'Address': pick(input.address, prev['Address']),
  'Service Needed': pick(input.serviceNeeded, prev['Service Needed']),
  'Description': pick(input.description, prev['Description']),
  'Photos Link': pick(input.photosLink, prev['Photos Link']),
  'Preferred Date': pick(input.preferredDate, prev['Preferred Date']),
  'Preferred Time': pick(input.preferredTime, prev['Preferred Time']),
  'Status': pick(input.status, prev['Status'] || 'New'),
  'Last Contact': now,
  'Follow-up Count': followUpCount,
  'Notes': pick(input.notes, prev['Notes']),
  'Confirmed Date': pick(input.confirmedDate, prev['Confirmed Date']),
  'Confirmed Time': pick(input.confirmedTime, prev['Confirmed Time']),
  'Send Confirmation': pick(input.sendConfirmation, prev['Send Confirmation'] || 'NO'),
  'Confirmation Sent': pick(input.confirmationSent, prev['Confirmation Sent'] || 'NO')
};
return [{
  json: {
    ...leadRow,
    _isNew: isNew
  }
}];

const s = $('Settings Loader').first().json;
const DEFAULT_TIMEZONE = s.timezone;
const nowET = () => DateTime.now().setZone(DEFAULT_TIMEZONE).toISO();

const leadRow = $('Resolve & Build Lead Row').first().json;
const input = $('Input').first().json;
const name = [leadRow['First Name'], leadRow['Last Name']].filter(Boolean).join(' ').trim();
const ts = nowET();
const logId = 'LOG-' + ts.replace(/[-:T.Z]/g, '').slice(0, 14) + '-' + Math.floor(Math.random() * 1000);
return [{ json: {
  'Log ID': logId,
  'Date/Time': ts,
  'Lead ID': leadRow['Lead ID'],
  'Customer Name': name,
  'Channel': input.logChannel || input.source || '',
  'Direction': input.logDirection || 'Inbound',
  'Handler': input.logHandler || 'AI',
  'Message Summary': input.logSummary || '',
  'Notes': input.logNotes || ''
}}];
